using System;using System.Globalization;using System.Security.Cryptography;using System.Text;using OpenMetaverse;using OpenSim.Framework;using OpenSim.Framework.AssetLoader.Filesystem;
namespace log4net{public interface ILog{void InfoFormat(string format,params object[] args);void ErrorFormat(string format,params object[] args);}public class Log:ILog{public void InfoFormat(string f,params object[] args)=>LoaderHost.Event("info:"+string.Format(f,args));public void ErrorFormat(string f,params object[] args){string value=string.Format(f,args);if(value.StartsWith("[ASSETS]: Error loading ")){int at=value.IndexOf(" : ");if(at>=0)value=value.Substring(0,at+3)+"XML";}LoaderHost.Event("error:"+value);}}public static class LogManager{public static ILog GetLogger(Type t)=>new Log();}}
public static class LoaderHost{public static string Trace,Fail;public static int Randoms;public static void Event(string value){Trace+=value+";";if(value==Fail)throw new Exception("injected");}public static UUID Random(){Event("random");return new UUID("00000000-0000-0000-0000-"+(++Randoms).ToString("x12"));}public static string Hex(string value)=>Convert.ToHexString(Encoding.UTF8.GetBytes(value)).ToLowerInvariant();public static string Text(string value)=>value=="N"?null:value=="."?"":Encoding.UTF8.GetString(Convert.FromHexString(value));}
class FilesystemAssetLoaderReference{static string Snapshot(AssetBase a)=>a.FullID+":"+LoaderHost.Hex(a.Name??"")+":"+a.Type+":"+LoaderHost.Hex(a.CreatorID??"")+":"+(a.Data==null?"N":Convert.ToHexString(SHA1.HashData(a.Data)).ToLowerInvariant())+":"+(a.Data==null?"N":a.Data.Length.ToString())+":"+LoaderHost.Hex(a.Description??"")+":"+(a.Local?1:0)+(a.Temporary?1:0);static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var parts=line.Split(' ');string path=LoaderHost.Text(parts[0]);int mode=int.Parse(parts[1]);LoaderHost.Trace="";LoaderHost.Fail=parts[2]=="-"?"":LoaderHost.Text(parts[2]);LoaderHost.Randoms=0;string values="",result="OK";bool reentered=false;var loader=new AssetLoaderFileSystem();Action<AssetBase> action=null;if(mode!=3)action=asset=>{values+=Snapshot(asset)+";";if(mode==1)throw new Exception("callback");if(mode==2&&!reentered){reentered=true;loader.ForEachDefaultXmlAsset(path,action);}};try{loader.ForEachDefaultXmlAsset(path,action);}catch{result="EX";}Console.WriteLine(result+"|"+values+"|"+LoaderHost.Hex(LoaderHost.Trace)+"|"+LoaderHost.Randoms);}}}
